def check_rules(R, N):
    # Rule (i): x in R => 2x in R
    for x in R:
        if 2*x <= N and 2*x not in R:
            return False
    # Rule (ii): x, y in R => x+y in R
    R_set = set(R)
    for x in R:
        for y in R:
            if x + y <= N and x + y not in R_set:
                return False
    return True

