def find_max_sum(N, min_R):
    import itertools

    best_sum = 0

    # Try d = 2
    R = [2*i for i in range(1, (N // 2) + 1)]
    if len(R) >= min_R:
        if check_rules(R, N):
            current_sum = sum(i for i in range(1, N + 1) if i not in R)
            best_sum = max(best_sum, current_sum)

    # Try R = {k, k+1, ..., N}
    for k in range(1, N + 1):
        R = list(range(k, N + 1))
        if len(R) >= min_R:
            if check_rules(R, N):
                current_sum = sum(i for i in range(1, N + 1) if i not in R)
                best_sum = max(best_sum, current_sum)

    return best_sum

